// Capture inbox journeys (#48) on `/w/chennai-solo/inbox`: three sections with live counts,
// confirming a proposal with `Enter` (a 7-second Undo toast, focus on the next card), the keyboard
// map, the unreadable-capture recovery copy, empty and offline states, a viewer's read-only cards
// and a non-member's not-found. The e2e stack has no job worker, so the specs seed proposals and
// captures with superuser SQL on the worker database. Fictional data only. Visual baselines live in
// e2e/__screenshots__/inbox and are only generated by the e2e workflow's `update_snapshots`.
import { randomUUID } from 'node:crypto';
import { existsSync } from 'node:fs';

import type { Page, TestInfo } from '@playwright/test';

import { expect, test } from '../../fixtures/index.ts';
import { WORKSPACE, WORKSPACE_ID, withSql } from '../lifecycle/helpers.ts';
import { shellReady } from '../shell/helpers.ts';

const INBOX = '/w/chennai-solo/inbox';

/** Drop what an earlier test seeded, then insert `tasks` proposals and the given captures. */
async function seedInbox(
  database: string,
  { tasks = 0, captures = [] as string[] }: { tasks?: number; captures?: string[] },
): Promise<void> {
  await withSql(database, async (sql) => {
    await sql`delete from proposal where workspace_id = ${WORKSPACE_ID} and idempotency_key like 'e2e-inbox-%'`;
    await sql`delete from capture where workspace_id = ${WORKSPACE_ID} and source_meta ->> 'e2eInbox' = '1'`;
    for (let n = 0; n < tasks; n += 1) {
      await sql`
        insert into proposal (id, workspace_id, kind, level, status, payload, idempotency_key, confidence)
        values (${randomUUID()}, ${WORKSPACE_ID}, 'task', 'L2', 'proposed',
          ${sql.json({ title: `File the counter ${String(n + 1)} (fictional)` })},
          ${`e2e-inbox-${String(n)}`}, 0.930)`;
    }
    for (const status of captures) {
      await sql`
        insert into capture (id, workspace_id, channel, status, mime, size_bytes, source_meta)
        values (${randomUUID()}, ${WORKSPACE_ID}, 'upload', ${status}, 'application/pdf', 1000,
          ${sql.json({ e2eInbox: '1' })})`;
    }
  });
}

async function openInbox(page: Page, asUser: Parameters<Parameters<typeof test>[2]>[0]['asUser']) {
  await asUser('owner', { workspace: WORKSPACE, path: INBOX.replace('/w/chennai-solo/', '') });
  await expect(page.getByRole('heading', { level: 1, name: 'Inbox' })).toBeVisible();
  await shellReady(page);
}

test.describe('capture inbox', () => {
  test('three sections with live counts', async ({ page, asUser, db }) => {
    await seedInbox(db.name, { tasks: 2, captures: ['processing', 'needs_you'] });
    await openInbox(page, asUser);
    const nav = page.getByRole('navigation', { name: 'Inbox sections' });
    await expect(nav.getByRole('button', { name: /Needs you/ })).toContainText('3');
    await expect(nav.getByRole('button', { name: /Ready to send/ })).toContainText('0');
    await expect(nav.getByRole('button', { name: /Processing/ })).toContainText('1');
    await nav.getByRole('button', { name: /Processing/ }).click();
    await expect(page.locator('[data-slot="capture-row"]')).toHaveCount(1);
  });

  test('Enter confirms the focused card, shows Undo and moves focus on', async ({
    page,
    asUser,
    db,
  }) => {
    await seedInbox(db.name, { tasks: 2 });
    await openInbox(page, asUser);
    const cards = page.locator('[data-proposal-id]');
    await cards.first().focus();
    await page.keyboard.press('Enter');
    await expect(page.getByText(/confirmed/i).first()).toBeVisible();
    await expect(page.getByRole('button', { name: 'Undo' })).toBeVisible();
    await expect(cards).toHaveCount(1);
    await expect(cards.first()).toBeFocused();
  });

  test('j and k move between cards; 1, 2 and 3 switch sections; ? opens the sheet', async ({
    page,
    asUser,
    db,
  }) => {
    await seedInbox(db.name, { tasks: 3 });
    await openInbox(page, asUser);
    const cards = page.locator('[data-proposal-id]');
    await cards.first().focus();
    await page.keyboard.press('j');
    await expect(cards.nth(1)).toBeFocused();
    await page.keyboard.press('k');
    await expect(cards.first()).toBeFocused();
    await page.keyboard.press('2');
    await expect(page.getByText('Nothing waiting to be sent.')).toBeVisible();
    await page.keyboard.press('?');
    await expect(page.getByRole('dialog', { name: 'Inbox shortcuts' })).toBeVisible();
  });

  test('an unreadable capture shows the recovery copy and its three actions', async ({
    page,
    asUser,
    db,
  }) => {
    await seedInbox(db.name, { captures: ['needs_you'] });
    await openInbox(page, asUser);
    await expect(
      page.getByText("Couldn't read this. Retake, type the key line, or keep as an attachment."),
    ).toBeVisible();
    await expect(page.getByRole('button', { name: 'Retake' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'Type the key line' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'Keep as attachment' })).toBeVisible();
  });

  test('empty states, and no Processing section when nothing is in flight', async ({
    page,
    asUser,
    db,
  }) => {
    await seedInbox(db.name, {});
    await openInbox(page, asUser);
    await expect(page.locator('[data-slot="inbox"]')).toContainText(
      /Nothing needs you\. Anything unclear will show up here\.|Capture once, confirm once\./,
    );
    await expect(page.locator('[data-slot="processing-list"]')).toHaveCount(0);
  });

  test('offline: banner shown and decisions off', async ({ page, asUser, context, db }) => {
    await seedInbox(db.name, { tasks: 1 });
    await openInbox(page, asUser);
    await context.setOffline(true);
    await expect(
      page.getByText(
        "You're offline. Captures are saved on this device and will process when you're back.",
      ),
    ).toBeVisible();
    await expect(page.getByRole('button', { name: 'Confirm' })).toBeDisabled();
    await context.setOffline(false);
  });

  test('a viewer sees read-only cards', async ({ page, asUser, db }) => {
    await seedInbox(db.name, { tasks: 1 });
    await asUser('viewer', { workspace: WORKSPACE, path: 'inbox' });
    await expect(page.getByRole('heading', { level: 1, name: 'Inbox' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'Confirm' })).toHaveCount(0);
  });
});

test.describe('capture inbox accessibility', { tag: '@a11y' }, () => {
  test('populated', async ({ page, asUser, db }) => {
    await seedInbox(db.name, { tasks: 2, captures: ['processing', 'needs_you'] });
    await openInbox(page, asUser);
    await expect(page.locator('[data-proposal-id]').first()).toBeVisible();
  });

  test('empty', async ({ page, asUser, db }) => {
    await seedInbox(db.name, {});
    await openInbox(page, asUser);
  });
});

function skipWithoutBaseline(testInfo: TestInfo, name: string) {
  const baseline = testInfo.snapshotPath(name, { kind: 'screenshot' });
  test.skip(
    testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
    'no baseline yet: dispatch the e2e workflow with update_snapshots',
  );
}

test.describe('capture inbox visual baselines', () => {
  for (const [name, seed] of [
    ['populated', { tasks: 2, captures: ['processing', 'needs_you'] }],
    ['empty', {}],
  ] as const) {
    test(name, async ({ page, asUser, db }, testInfo) => {
      skipWithoutBaseline(testInfo, `inbox-${name}.png`);
      await seedInbox(db.name, { ...seed, captures: [...(seed.captures ?? [])] });
      await openInbox(page, asUser);
      await expect(page).toHaveScreenshot(`inbox-${name}.png`, { fullPage: true });
    });
  }
});
